/**
 * Argument parsing per the README.
 *
 * `--retry <n>` sets the retry count (default 0). `--retry` without a
 * following numeric value is an error.
 */
export function parseArgs(argv) {
  const index = argv.indexOf('--retry')
  if (index === -1) return { retries: 0 }

  const raw = argv[index + 1]
  if (raw === undefined || raw.startsWith('-')) {
    throw new Error('--retry requires a value')
  }
  const retries = Number(raw)
  if (!Number.isInteger(retries) || retries < 0) {
    throw new Error(`invalid --retry value: ${raw}`)
  }
  return { retries }
}

/**
 * Retry logic per the README. Transient network errors (code
 * `ETIMEDOUT` / `ECONNRESET`) are retried up to `retries` times with a
 * short linear backoff delay; any other error propagates immediately.
 */
const TRANSIENT_CODES = new Set(['ETIMEDOUT', 'ECONNRESET'])

const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms))

export async function retryWithBackoff(fn, retries) {
  for (let attempt = 0; ; attempt += 1) {
    try {
      return await fn()
    } catch (error) {
      if (attempt >= retries || !TRANSIENT_CODES.has(error?.code)) throw error
      await sleep(5 * (attempt + 1)) // small delay; keep it short for tests
    }
  }
}

args.old_string:
const transient = (message) => {
  const error = new Error(message)
  error.code = 'ETIMEDOUT'
  return error
}

args.new_string:
const transient = (message) => {
  const error = new Error(message)
  error.code = 'ETIMEDOUT'
  return error
}

const withCode = (message, code) => {
  const error = new Error(message)
  error.code = code
  return error
}

test('retry: gives up after retries are exhausted', async () => {
  await assert.rejects(() => retryWithBackoff(() => Promise.reject(transient('timeout')), 2))
})

test('retry: retries ECONNRESET failures too', async () => {
  let calls = 0
  const result = await retryWithBackoff(() => {
    calls += 1
    if (calls === 1) return Promise.reject(withCode('reset', 'ECONNRESET'))
    return Promise.resolve('ok')
  }, 3)
  assert.equal(result, 'ok')
  assert.equal(calls, 2)
})

test('retry: does not retry non-transient errors', async () => {
  let calls = 0
  await assert.rejects(() =>
    retryWithBackoff(() => {
      calls += 1
      return Promise.reject(withCode('permission denied', 'EACCES'))
    }, 3)
  )
  assert.equal(calls, 1)
})

test('retry: does not retry when retries is 0', async () => {
  let calls = 0
  await assert.rejects(() =>
    retryWithBackoff(() => {
      calls += 1
      return Promise.reject(transient('timeout'))
    }, 0)
  )
  assert.equal(calls, 1)
})

test('retry: >= 99% success under simulated 30% packet loss with 3 retries', async () => {
  const trials = 1000
  // Deterministic LCG so the outcome is reproducible, not flaky.
  let seed = 123456789
  const rand = () => {
    seed = (seed * 1664525 + 1013904223) >>> 0
    return seed / 4294967296
  }

  let successes = 0
  for (let i = 0; i < trials; i += 1) {
    try {
      await retryWithBackoff(
        () => (rand() < 0.3 ? Promise.reject(transient('timeout')) : Promise.resolve('ok')),
        3
      )
      successes += 1
    } catch {
      // all 4 attempts failed — count as a failed trial
    }
  }

  const rate = successes / trials
  assert.ok(rate >= 0.99, `success rate ${rate} < 0.99`)
})

